import 'dart:math';

import 'package:loremark/story_model/story_model.dart';

/// Seeded story models for the spoiler audit and the scalability benchmark,
/// so neither needs a real model generated by the lab.
///
/// The JSON follows the lab's cumulative schema (2.0) and goes through
/// [StoryModel.fromJson], so loading is exercised too. It is built to stress
/// what `StorySnapshot` must get right: facts that are superseded, retracted
/// or resolved in later sections, renamed entities, and identity links that
/// merge entities, including links that are themselves retracted later.
///
/// Every free-text field ends with a tag like `{s012}` naming the section
/// the text was learned in, so a check can see which sections a string it was
/// shown came from. Pure Dart, no Flutter imports.

/// Size and shape of a generated model.
class SyntheticStoryModelSpec {
  const SyntheticStoryModelSpec({
    this.seed = 1,
    this.sections = 40,
    this.characters = 120,
    this.locations = 12,
    this.organizations = 6,
    this.records = 1500,
    this.transitionRate = 0.3,
    this.identityLinks = 14,
  });

  final int seed;
  final int sections;
  final int characters;
  final int locations;
  final int organizations;

  /// Roughly how many records to create across all collections, before the
  /// replacements and identity links that transitions and reveals add.
  final int records;

  /// Share of records that a later section supersedes, retracts or resolves.
  final double transitionRate;

  /// Identity links to plant, some retracted later and some cross-kind.
  final int identityLinks;

  /// The size the scalability spec asks for: about 2,000 characters and
  /// 20,000 records across 100 sections.
  static const large = SyntheticStoryModelSpec(
    sections: 100,
    characters: 2000,
    locations: 200,
    organizations: 100,
    records: 20000,
    identityLinks: 60,
  );
}

/// A generated model and the facts the generator knows about it.
class SyntheticStoryModel {
  SyntheticStoryModel._(this.json, this.introducedIn, this.recordCounts);

  /// The model as `story_model.json` text decoded to maps and lists.
  final Map<String, dynamic> json;

  /// The section order in which each entity is first named by a record.
  final Map<String, int> introducedIn;

  /// How many records mention each entity.
  final Map<String, int> recordCounts;

  late final StoryModel model = StoryModel.fromJson(json);
}

/// `s007` for section order 7.
String syntheticSectionId(int order) => 's${order.toString().padLeft(3, '0')}';

/// The tag the generator appends to text learned in section [order].
String syntheticTag(int order) => '{${syntheticSectionId(order)}}';

final _tagPattern = RegExp(r'\{s(\d+)\}');

/// The section orders named by tags in [text].
Iterable<int> sectionTagsIn(String text) =>
    _tagPattern.allMatches(text).map((m) => int.parse(m[1]!));

SyntheticStoryModel generateSyntheticStoryModel([
  SyntheticStoryModelSpec spec = const SyntheticStoryModelSpec(),
]) => _Generator(spec).generate();

class _Entity {
  _Entity(this.id, this.kind, this.intro);

  final String id;
  final String kind;

  /// Section order of the entity's first record.
  final int intro;
}

/// Entities of one kind in order of introduction, to pick from the ones the
/// reader has met by a section.
class _Pool {
  _Pool(this.entities, int sections) {
    entities.sort((a, b) => a.intro.compareTo(b.intro));
    var index = 0;
    for (var s = 0; s <= sections; s++) {
      while (index < entities.length && entities[index].intro <= s) {
        index++;
      }
      _countUpTo.add(index);
    }
  }

  final List<_Entity> entities;
  final _countUpTo = <int>[];

  int countUpTo(int section) => _countUpTo[section];
}

class _Generator {
  _Generator(this.spec) : random = Random(spec.seed);

  final SyntheticStoryModelSpec spec;
  final Random random;

  late final _Pool characters;
  late final _Pool locations;
  late final _Pool organizations;
  final entityKind = <String, String>{};
  final introducedIn = <String, int>{};
  final recordCounts = <String, int>{};

  final records = <String, List<Map<String, dynamic>>>{
    'names': [],
    'aliases': [],
    'attributes': [],
    'relationships': [],
    'events': [],
    'uncertainties': [],
    'identity_links': [],
  };
  final transitions = <Map<String, dynamic>>[];
  var _recordNumber = 0;

  /// Records no transition has targeted yet, and their collection.
  final _open = <({String collection, Map<String, dynamic> record})>[];

  static const _labels = [
    'occupation', 'home', 'age', 'allegiance', 'appearance', 'goal', //
    'fear', 'rank', 'weapon', 'secret',
  ];
  static const _relationLabels = [
    'member_of', 'sibling_of', 'watches', 'trusts', 'owes', 'rival_of', //
    'mentor_of', 'serves',
  ];
  static const _assertions = ['explicit', 'explicit', 'reported', 'inferred'];
  static const _temporal = ['current', 'current', 'past', 'future'];

  SyntheticStoryModel generate() {
    _createEntities();
    _createRecords();
    _createIdentityLinks();
    _createTransitions();
    return SyntheticStoryModel._(_toJson(), introducedIn, recordCounts);
  }

  int _randomSection() => 1 + random.nextInt(spec.sections);

  void _createEntities() {
    List<_Entity> make(String prefix, String kind, int count) => [
      for (var i = 1; i <= count; i++)
        _Entity(
          '$prefix${i.toString().padLeft(4, '0')}',
          kind,
          // Some entities appear early, the rest spread over the book.
          i <= count ~/ 8 ? 1 : _randomSection(),
        ),
    ];
    characters = _Pool(make('c', 'character', spec.characters), spec.sections);
    locations = _Pool(make('l', 'location', spec.locations), spec.sections);
    organizations = _Pool(
      make('g', 'organization', spec.organizations),
      spec.sections,
    );
    for (final pool in [characters, locations, organizations]) {
      for (final entity in pool.entities) {
        entityKind[entity.id] = entity.kind;
        introducedIn[entity.id] = entity.intro;
        _add('names', entity.intro, {
          'entity_id': entity.id,
          'text': 'Name ${entity.id} ${syntheticTag(entity.intro)}',
        });
        if (random.nextInt(3) == 0) {
          _add('aliases', entity.intro, {
            'entity_id': entity.id,
            'text': 'Alias ${entity.id} ${syntheticTag(entity.intro)}',
          });
        }
      }
    }
  }

  /// A character the reader has met by [section], skewed to early ones so a
  /// few characters collect many facts, as in a real book.
  String _character(int section) {
    final count = characters.countUpTo(section);
    return characters
        .entities[(count * pow(random.nextDouble(), 2)).floor()]
        .id;
  }

  String? _other(_Pool pool, int section) {
    final count = pool.countUpTo(section);
    return count == 0 ? null : pool.entities[random.nextInt(count)].id;
  }

  /// Any entity the reader has met by [section].
  String _anyEntity(int section) {
    final roll = random.nextInt(10);
    final pool = roll == 0
        ? locations
        : roll == 1
        ? organizations
        : characters;
    return _other(pool, section) ?? _character(section);
  }

  Map<String, dynamic> _add(
    String collection,
    int section,
    Map<String, dynamic> payload, {
    bool track = true,
  }) {
    final record = <String, dynamic>{
      'id': 'f${(++_recordNumber).toString().padLeft(6, '0')}',
      'introduced_revision': section,
      'learned_in_section_id': syntheticSectionId(section),
      'payload': payload,
      'evidence': _evidence(section),
    };
    records[collection]!.add(record);
    if (track) _open.add((collection: collection, record: record));
    for (final entry in payload.entries) {
      final value = entry.value;
      final ids = value is String && entityKind.containsKey(value)
          ? [value]
          : value is List
          ? value.whereType<String>().where(entityKind.containsKey)
          : const <String>[];
      for (final id in ids) {
        recordCounts[id] = (recordCounts[id] ?? 0) + 1;
      }
    }
    return record;
  }

  /// One or two quotes from [section] or a section just before it.
  List<Map<String, dynamic>> _evidence(int section) => [
    for (var i = 0; i < 1 + random.nextInt(2); i++)
      () {
        final cited = max(1, section - random.nextInt(3));
        return {
          'section_id': syntheticSectionId(cited),
          'paragraph_id': 'p${random.nextInt(300).toString().padLeft(4, '0')}',
          'quote': 'Quote ${syntheticTag(cited)}',
        };
      }(),
  ];

  Map<String, dynamic> _payload(String collection, int section) {
    final tag = syntheticTag(section);
    switch (collection) {
      case 'aliases':
      case 'names':
        return {
          'entity_id': _character(section),
          'text': 'Alias $_recordNumber $tag',
        };
      case 'attributes':
        return {
          'entity_id': _anyEntity(section),
          'label': _labels[random.nextInt(_labels.length)],
          'value': 'Value $_recordNumber $tag',
          'assertion': _assertions[random.nextInt(_assertions.length)],
          'attributed_to_id': random.nextInt(10) == 0
              ? _character(section)
              : null,
        };
      case 'relationships':
        return {
          'source_id': _character(section),
          'target_id': _anyEntity(section),
          'label': _relationLabels[random.nextInt(_relationLabels.length)],
          'description': 'Relation $_recordNumber $tag',
          'assertion': _assertions[random.nextInt(_assertions.length)],
          'attributed_to_id': null,
          'temporal_context': _temporal[random.nextInt(_temporal.length)],
        };
      case 'events':
        return {
          'description': 'Event $_recordNumber $tag',
          'participant_ids': {
            for (var i = 0; i < 1 + random.nextInt(3); i++) _character(section),
          }.toList(),
          'location_id': _other(locations, section),
          'narrative_order': random.nextInt(6),
          'temporal_context': _temporal[random.nextInt(_temporal.length)],
          'story_time': null,
          'assertion': _assertions[random.nextInt(_assertions.length)],
          'attributed_to_id': null,
        };
      case 'uncertainties':
        return {
          'question': 'Question $_recordNumber $tag',
          'related_entity_ids': {
            for (var i = 0; i < 1 + random.nextInt(2); i++) _character(section),
          }.toList(),
        };
    }
    throw ArgumentError(collection);
  }

  void _createRecords() {
    const weights = {
      'attributes': 45,
      'relationships': 20,
      'events': 20,
      'uncertainties': 10,
      'aliases': 5,
    };
    final bag = [
      for (final entry in weights.entries)
        for (var i = 0; i < entry.value; i++) entry.key,
    ];
    while (_recordNumber < spec.records) {
      final collection = bag[random.nextInt(bag.length)];
      final section = _randomSection();
      _add(collection, section, _payload(collection, section));
    }
  }

  /// Reveals that two entities are one. Some pairs are of different kinds,
  /// which a snapshot must ignore, some are only inferred, and some chain onto
  /// the previous link so several entities merge into one.
  void _createIdentityLinks() {
    String? previous;
    for (var i = 0; i < spec.identityLinks; i++) {
      final section = 2 + random.nextInt(max(1, spec.sections - 1));
      // A chained link can only name an entity the reader has met by then.
      final chained = previous != null && introducedIn[previous]! <= section;
      final left = chained ? previous : _character(section);
      final crossKind = random.nextInt(8) == 0;
      final right =
          (crossKind ? _other(organizations, section) : null) ??
          _character(section);
      if (left == right) continue;
      previous = random.nextInt(4) == 0 ? right : null;
      _add('identity_links', section, {
        'left_entity_id': left,
        'right_entity_id': right,
        'assertion': random.nextInt(5) == 0 ? 'inferred' : 'explicit',
        'explanation': 'Same person $_recordNumber ${syntheticTag(section)}',
      });
    }
  }

  void _createTransitions() {
    final candidates = [..._open]..shuffle(random);
    final goal = (candidates.length * spec.transitionRate).round();
    var made = 0;
    for (var i = 0; i < candidates.length && made < goal; i++) {
      final (:collection, :record) = candidates[i];
      final learned = _sectionOrder(record['learned_in_section_id'] as String);
      if (learned >= spec.sections) continue;
      // The later section may be the very next one or far later.
      final section = learned + 1 + random.nextInt(spec.sections - learned);
      final action = _chooseAction(collection);
      String? replacementId;
      String? resolution;
      if (action == 'supersede') {
        final replacement = _add(
          collection,
          section,
          _replacement(
            collection,
            record['payload'] as Map<String, dynamic>,
            section,
          ),
          track: false,
        );
        replacementId = replacement['id'] as String;
        // Let a replacement be replaced in turn, to build chains.
        if (random.nextInt(4) == 0) {
          candidates.add((collection: collection, record: replacement));
        }
      } else if (action == 'resolve') {
        resolution = 'Answer ${syntheticTag(section)}';
      }
      transitions.add({
        'id': 't${(transitions.length + 1).toString().padLeft(6, '0')}',
        'introduced_revision': section,
        'learned_in_section_id': syntheticSectionId(section),
        'target_record_id': record['id'],
        'action': action,
        'replacement_record_id': replacementId,
        'resolution': resolution,
        'reason': 'Reason ${syntheticTag(section)}',
        'evidence': _evidence(section),
      });
      made++;
    }
    // The real lab appends transitions as it commits each section.
    transitions.sort(
      (a, b) => (a['introduced_revision'] as int).compareTo(
        b['introduced_revision'] as int,
      ),
    );
  }

  String _chooseAction(String collection) {
    final roll = random.nextInt(100);
    switch (collection) {
      case 'uncertainties':
        return roll < 60
            ? 'resolve'
            : roll < 75
            ? 'retract'
            : 'supersede';
      case 'identity_links':
        return roll < 80 ? 'retract' : 'supersede';
      default:
        return roll < 70 ? 'supersede' : 'retract';
    }
  }

  /// The payload of a record that replaces one with [old], about the same
  /// entities, with new text.
  Map<String, dynamic> _replacement(
    String collection,
    Map<String, dynamic> old,
    int section,
  ) {
    final tag = syntheticTag(section);
    final copy = Map<String, dynamic>.of(old);
    for (final key in [
      'text',
      'value',
      'description',
      'question',
      'explanation',
    ]) {
      if (copy.containsKey(key)) copy[key] = 'Replaced $_recordNumber $tag';
    }
    return copy;
  }

  int _sectionOrder(String id) => int.parse(id.substring(1));

  Map<String, dynamic> _toJson() => {
    'schema_version': '2.0',
    'scope': 'cumulative',
    'book': {'title': 'The Synthetic Harbor', 'epub_sha256': 'synthetic'},
    'revision': {'number': spec.sections},
    // The lab does not promise an order; StoryModel sorts them.
    'processed_sections': [
      for (var order = spec.sections; order >= 1; order--)
        {
          'section_id': syntheticSectionId(order),
          'section_order': order,
          'chapter_number': order,
          'title': 'Chapter $order',
        },
    ],
    'entities': [
      for (final pool in [characters, locations, organizations])
        for (final entity in pool.entities)
          {
            'id': entity.id,
            'kind': entity.kind,
            'introduced_revision': entity.intro,
          },
    ],
    'records': records,
    'transitions': transitions,
  };
}
